function cleanPost (méthode, version, arguments, rappel){
    var loadT = layer.msg('Obtenir...', { icône : 16, heure : 0, ombre : 0,3 });

    var req_data = {};
    req_data['nom'] = 'propre';
    req_data['func'] = méthode ;
    req_data['version'] = version;

    if (typeof(args) == 'string'){
        req_data['args'] = JSON.stringify(toArrayObject(args));
    } autre {
        req_data['args'] = JSON.stringify(args);
    }

    $.post('/plugins/run', req_data, fonction(données) {
        layer.close(loadT);
        si (!data.status){
            layer.msg(data.msg,{icon:0,time:2000,shade: [10, '#000']});
            retour;
        }

        if(typeof(callback) == 'fonction'){
            rappel (données);
        }
    },'json');
}

